import React,{useEffect,useMemo,useRef,useState} from 'react';
import {LayoutDashboard,Link2,Receipt,Wallet,ShieldCheck,FileBarChart,Users,Layers,Menu,RefreshCw,Plus,Download,Search,ChevronDown,ChevronRight,Bell,CalendarDays,ArrowUpRight,ArrowDownRight,TrendingUp,TrendingDown,Target,MousePointerClick,Activity,MoreHorizontal,X,Check,AlertTriangle,Clock3,Eye,SlidersHorizontal,Filter,LogOut,Command,CheckCircle2,FileText,Shield,Cloud,Smartphone,Info,ArrowRight,Sun,Moon,Upload,Building2,Briefcase,PanelLeftClose,PanelLeftOpen,ChartNoAxesCombined,CheckCheck,Pencil,Trash2} from 'lucide-react';
import {displayRef} from './utils/display-id';
import {ResponsiveContainer,AreaChart,Area,XAxis,YAxis,CartesianGrid,Tooltip,BarChart,Bar,Cell,PieChart,Pie} from 'recharts';

import {api} from './api/client.jsx';
import { useAuth } from '../lib/auth.jsx';
import ExpenseAuditPanel from './components/ExpenseAuditPanel.jsx';
import AdAccountsPage from './components/AdAccountsPage.jsx';
import {ReportingPeriodPicker,defaultPeriod,periodQuery,periodLabel} from './components/ReportingPeriodPicker.jsx';
import CounsellorAttributionPage from './components/CounsellorAttributionPage.jsx';
import {displaySpendPKR,sourceCurrencyNote} from './utils/currency.js';
import {styles, uiPolishStyles, budgetFinalStyles} from './theme.jsx';
const NAV=[['Dashboard',LayoutDashboard],['Ad Accounts',Link2],['Counsellor Attribution',Target],['Expenses',Receipt],['Budgets',Wallet],['Audit & Approvals',ShieldCheck],['Reports',FileBarChart],['Categories',Layers]];
const money=n=>'Rs. '+Number(n||0).toLocaleString('en-PK');
const chartPalette=['#1774bd','#51b5e5','#82d9ec'];
const monthNow=()=>{const d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}`;};
const today=()=>{const d=new Date();const offset=d.getTimezoneOffset()*60000;return new Date(d.getTime()-offset).toISOString().slice(0,10)};
const icons=[Receipt,Target,Briefcase,Activity,Layers,FileText,Cloud,Wallet,Users];
function Pill({children,tone='blue',dot=false}){return <span className={'pill pill-'+tone}>{dot&&<i className="pill-dot"/>}{children}</span>}
function Btn({children,variant='primary',onClick,disabled=false,icon:Icon,type='button',className=''}){return <button type={type} disabled={disabled} onClick={onClick} className={'btn btn-'+variant+' '+className}>{Icon&&<Icon size={16}/>} {children}</button>}
function Card({children,className='',style}){return <section className={'surface-card '+className} style={style}>{children}</section>}
function Heading({eyebrow,title,subtitle,action}){return <div className="page-heading"><div><div className="eyebrow">{eyebrow||'SCHOLARSHIPHIVE / MEA'}</div><h1>{title}</h1><p>{subtitle}</p></div>{action&&<div className="heading-action">{action}</div>}</div>}
function Panel({title,sub,right,children,className=''}){return <Card className={'panel '+className}><div className="panel-head"><div><h3>{title}</h3>{sub&&<p>{sub}</p>}</div>{right}</div>{children}</Card>}
function Empty({title='No records found',desc='Try changing your filters.'}){return <div className="empty"><Search size={26}/><strong>{title}</strong><span>{desc}</span></div>}
function DataTable({head,children}){return <div className="table-scroll"><table><thead><tr>{head.map(h=><th key={h}>{h}</th>)}</tr></thead><tbody>{children}</tbody></table></div>}
function Progress({value,color}){return <div className="progress"><div style={{width:Math.min(100,Math.max(0,value))+'%',background:color||(value>=85?'#eaa243':'linear-gradient(90deg,#0865a4,#51b5e5)')}}/></div>}
function Modal({title,sub,onClose,children}){useEffect(()=>{const fn=e=>{if(e.key==='Escape')onClose()};document.addEventListener('keydown',fn);return()=>document.removeEventListener('keydown',fn)},[onClose]);return <div className="modal-backdrop" onMouseDown={e=>{if(e.target===e.currentTarget)onClose()}}><div className="modal-box" role="dialog" aria-modal="true" aria-label={title}><div className="modal-head"><div><h2>{title}</h2>{sub&&<p>{sub}</p>}</div><button className="icon-btn" aria-label="Close popup" onClick={onClose}><X size={20}/></button></div>{children}</div></div>}
export default function App(){
 const { user, can, isAdmin } = useAuth();
 if (!user || !can('marketing')) return <div className="mea-access-denied"><h2>Access denied</h2><p>Your ScholarshipHive account does not have Marketing Analyzer permission. Ask an administrator to grant access.</p></div>;
 const marketingUser = {
   id: String(user.id), name: user.full_name || 'ERP User', email: user.email || '',
   role: isAdmin ? 'Admin' : 'Employee', status: 'Active',
   canEdit: isAdmin || can('marketing', 'edit'),
   initials: String(user.full_name || 'ERP').split(/\s+/).slice(0,2).map(x=>x[0]).join('').toUpperCase(),
 };
 return <Workspace key={user.id} session={{ user: marketingUser }} onLogout={() => {}} />;
}
function Workspace({session,onLogout}){
 const currentUser=session.user;
 const isAdmin=currentUser.role==='Admin';
 const canEdit=Boolean(currentUser.canEdit || isAdmin);
 const [page,setPage]=useState('Dashboard'),[compact,setCompact]=useState(false),[mobileMenu,setMobileMenu]=useState(false);
 const [expenses,setExpenses]=useState([]),[team,setTeam]=useState([]);
 const [accounts,setAccounts]=useState([]),[categories,setCategories]=useState([]),[categoryTree,setCategoryTree]=useState([]);
 const [budgets,setBudgets]=useState([]),[myBudgets,setMyBudgets]=useState({items:[],overall:{limit:0,used:0,pending:0,availableToCreate:0}}),[employeeBudgets,setEmployeeBudgets]=useState([]),[expenseAllowance,setExpenseAllowance]=useState(null),[editAllowance,setEditAllowance]=useState(null),[dashboard,setDashboard]=useState(null),[chartData,setChartData]=useState([]);
 const [apiOnline,setApiOnline]=useState(false),[loading,setLoading]=useState(true),[loadError,setLoadError]=useState('');
 const [budgetMonth,setBudgetMonth]=useState(monthNow()),[search,setSearch]=useState(''),[filter,setFilter]=useState('All'),[modal,setModal]=useState(null),[toast,setToast]=useState(''),[notice,setNotice]=useState(false),[dark,setDark]=useState(false),[range,setRange]=useState('This month');
 const [form,setForm]=useState({title:'',category:'',subcategory:'',amount:'',date:today(),vendor:'',reference:'',description:''});
 const [editForm,setEditForm]=useState({}),[pendingDelete,setPendingDelete]=useState(null);
 const [categoryForm,setCategoryForm]=useState(''),[subcategoryForm,setSubcategoryForm]=useState({categoryId:'',name:''});
 const [assignForm,setAssignForm]=useState({month:monthNow(),userId:'',category:'',subcategory:'',limit:''}),[editAssignForm,setEditAssignForm]=useState({id:'',limit:''});
 const [budgetForm,setBudgetForm]=useState({id:'',limit:''}),[newBudget,setNewBudget]=useState({month:monthNow(),category:'',subcategory:'',limit:''}),[auditHistory,setAuditHistory]=useState([]);
 const [reportingPeriod,setReportingPeriod]=useState(()=>{try{return JSON.parse(sessionStorage.getItem('mea-report-period'))||defaultPeriod()}catch{return defaultPeriod()}});
 const reportQuery=periodQuery(reportingPeriod);
 useEffect(()=>{sessionStorage.setItem('mea-report-period',JSON.stringify(reportingPeriod));if(reportingPeriod.mode==='month')setBudgetMonth(reportingPeriod.month)},[reportingPeriod]);
 const firstAdRefresh=useRef(false);
 const loadData=async()=>{
   setLoading(true);
   try {
     const [cats,exps,summary,own,adAccounts]=await Promise.all([api.categories(),api.expenses(),api.dashboard(budgetMonth,reportQuery),api.myBudgets(budgetMonth),api.accounts(reportQuery)]);
     const names=cats.map(c=>c.name);
     setCategoryTree(cats);setCategories(names);setExpenses(exps);setDashboard(summary);setMyBudgets(own);setAccounts(adAccounts);
     // Browser reload requests fresh platform data for already verified accounts;
     // backend throttles and deduplicates the actual external API sync jobs.
     if(canEdit && !firstAdRefresh.current){
       firstAdRefresh.current=true;
       adAccounts.filter(a=>a.lastVerifiedAt).forEach(a=>api.refreshAdAccount(a.id).catch(()=>{}));
     }
     if(isAdmin){
       const [buds,users,report,assigned]=await Promise.all([api.budgets(budgetMonth),api.users(),api.reports(reportQuery),api.employeeBudgets(budgetMonth)]);
       setEmployeeBudgets(assigned.items);
       setBudgets(buds.items.length?[{name:'Overall Marketing Budget',...buds.overall,caption:'Company-wide · '+budgetMonth},...buds.items]:[]);
       setTeam(users);setChartData(report.chartData);
     }else{setBudgets([]);setEmployeeBudgets([]);setTeam([]);setChartData([])}
     setApiOnline(true);setLoadError('');
   } catch(err){
     setApiOnline(false);setLoadError(err.message);
   } finally {setLoading(false)}
 };
 useEffect(()=>{loadData()},[budgetMonth,reportingPeriod.mode,reportingPeriod.month,reportingPeriod.startDate,reportingPeriod.endDate]);
 useEffect(()=>{
   let alive=true;
   const month=(form.date||today()).slice(0,7);
   api.myBudgets(month).then(data=>{if(alive)setExpenseAllowance(data)}).catch(()=>{if(alive)setExpenseAllowance(null)});
   return ()=>{alive=false};
 },[form.date,modal==='expense']);
 useEffect(()=>{
   if(modal!=='expenseEdit')return;
   let alive=true;
   api.myBudgets((editForm.date||today()).slice(0,7)).then(data=>{if(alive)setEditAllowance(data)}).catch(()=>{if(alive)setEditAllowance(null)});
   return ()=>{alive=false};
 },[editForm.date,modal==='expenseEdit']);

 useEffect(()=>{if(!toast)return;let t=setTimeout(()=>setToast(''),3400);return()=>clearTimeout(t)},[toast]);
 const notify=(msg)=>setToast(msg);
 const navigate=x=>{if(!isAdmin && !['Dashboard','Ad Accounts','Counsellor Attribution','Expenses','Budgets','Categories'].includes(x))return;setPage(x);setMobileMenu(false);setSearch('');setFilter('All');window.scrollTo({top:0,behavior:'smooth'})};
 const isPastBudgetMonth=budgetMonth < monthNow();
 const subcategoriesFor=(name)=>categoryTree.find(c=>c.name===name)?.subcategories||[];
 const selectedAllowance=expenseAllowance?.items?.find(a=>a.category===form.category&&a.subcategory===form.subcategory);
 const editSelectedAllowance=editAllowance?.items?.find(a=>a.category===editForm.category&&a.subcategory===editForm.subcategory);
 const canCreateExpense=Boolean(canEdit&&selectedAllowance&&Number(form.amount)>0&&Number(form.amount)<=selectedAllowance.availableToCreate);
 const canEditExpense=Boolean(canEdit&&editSelectedAllowance&&Number(editForm.amount)>0&&Number(editForm.amount)<=((editSelectedAllowance.availableToCreate||0)+(expenses.find(e=>e.id===editForm.id&&e.category===editForm.category&&e.subcategory===editForm.subcategory&&e.date.slice(0,7)===editForm.date?.slice(0,7))?.amount||0)));
 const filtered=useMemo(()=>expenses.filter(e=>(reportingPeriod.mode==='month'?e.date?.startsWith(reportingPeriod.month):e.date>=reportingPeriod.startDate&&e.date<=reportingPeriod.endDate)&&[e.title,e.category,e.owner||'',e.ownerId||'',e.status].join(' ').toLowerCase().includes(search.toLowerCase())&&(filter==='All'||e.status===filter)),[expenses,search,filter,reportingPeriod]);
 const addExpense=async e=>{
   e.preventDefault();
   if(!canEdit){notify('Your ScholarshipHive Expenses permission is view-only.');return;}
   if(!apiOnline){notify('Connect to the ScholarshipHive server to save expenses');return;}
   try {
     await api.createExpense({...form,amount:Number(form.amount)});
     await loadData();setModal(null);
     setForm({title:'',category:'',subcategory:'',amount:'',date:today(),vendor:'',reference:'',description:''});
     notify('Expense saved successfully');
   }catch(err){notify(err.message)}
 };

 const openEditExpense=e=>{
   if(!canEdit){notify('Your ScholarshipHive Expenses permission is view-only.');return;}
   setEditForm({id:e.id,title:e.title,category:e.category,subcategory:e.subcategory||'',amount:String(e.amount),date:e.date,vendor:e.vendor||'',reference:e.reference||'',description:e.description||''});
   setModal('expenseEdit');
 };
 const saveEditedExpense=async event=>{
   event.preventDefault();
   if(!canEdit){notify('Your ScholarshipHive Expenses permission is view-only.');return;}
   try{await api.updateExpense(editForm.id,{title:editForm.title,category:editForm.category,subcategory:editForm.subcategory,amount:Number(editForm.amount),date:editForm.date,vendor:editForm.vendor,reference:editForm.reference,description:editForm.description});await loadData();setModal(null);notify('Expense updated')}
   catch(err){notify(err.message)}
 };
 const deleteExpense=async()=>{
   if(!canEdit){notify('Your ScholarshipHive Expenses permission is view-only.');return;}
   if(!pendingDelete)return;
   try{await api.deleteExpense(pendingDelete.id);await loadData();setModal(null);setPendingDelete(null);notify('Pending expense deleted')}
   catch(err){notify(err.message)}
 };
 const createBudget=async event=>{
   event.preventDefault();
   if(newBudget.month<monthNow())return notify('Past months are read-only');
   try{await api.createBudget({...newBudget,limit:Number(newBudget.limit)});if(newBudget.month===budgetMonth){await loadData()}else{setBudgetMonth(newBudget.month)}setModal(null);notify('Monthly budget allocation created')}
   catch(err){notify(err.message)}
 };
 const createEmployeeBudget=async e=>{
   e.preventDefault();
   try{await api.allocateEmployee({...assignForm,limit:Number(assignForm.limit)});setModal(null);await loadData();notify('Employee category budget assigned')}
   catch(err){notify(err.message)}
 };
 const editEmployeeBudget=async e=>{
   e.preventDefault();
   try{await api.updateEmployeeBudget(editAssignForm.id,Number(editAssignForm.limit));setModal(null);await loadData();notify('Employee allocation updated')}
   catch(err){notify(err.message)}
 };
 const addCategory=async e=>{
   e.preventDefault();if(!apiOnline){notify('Start backend first');return;}
   try {await api.createCategory(categoryForm);await loadData();setModal(null);setCategoryForm('');notify('Category added');}
   catch(err){notify(err.message)}
 };
 const addSubcategory=async e=>{e.preventDefault();try{await api.createSubcategory(subcategoryForm.categoryId,subcategoryForm.name);await loadData();setSubcategoryForm({categoryId:'',name:''});setModal(null);notify('Subcategory added')}catch(err){notify(err.message)}};
 const updateBudget=async e=>{
   e.preventDefault();
   if(isPastBudgetMonth)return notify('Past months are read-only');if(!apiOnline){notify('Start backend first');return;}
   try {await api.updateBudget(budgetForm.id,Number(budgetForm.limit));await loadData();setModal(null);notify('Budget updated');}
   catch(err){notify(err.message)}
 };
 const reviewExpense=async(id,action)=>{
   if(!apiOnline){notify('Start backend first');return;}
   try {await api.auditDecision(id,action);await loadData();setModal(null);notify(`Expense ${action==='approve'?'approved':action==='reject'?'rejected':'moved to review'} `);}
   catch(err){notify(err.message)}
 };
 const viewExpense=async e=>{
   setAuditHistory([]);setModal({type:'expenseDetail',data:e});
   if(apiOnline)try{setAuditHistory(await api.expenseHistory(e.id))}catch{}
 };
 const refreshExpenseModal=async id=>{
   await loadData();
   const latest=await api.expense(id);
   setModal(current=>current?.type==='expenseDetail'?{type:'expenseDetail',data:latest}:current);
 };

 const refresh=async()=>{await loadData();notify('Updated from backend; verified ad accounts requested fresh sync')};
 const topAction=canEdit?<Btn icon={Plus} onClick={()=>setModal('expense')}>Add Expense</Btn>:null;
 const expenseTable=(rows)=> <DataTable head={isAdmin?['EXPENSE / DESCRIPTION','CREATED BY (USER ID)','CATEGORY','AMOUNT','DATE','STATUS','']:['EXPENSE / DESCRIPTION','CATEGORY','AMOUNT','DATE','STATUS','']}>
 {rows.length?rows.map(e=><tr key={e.id}>
   <td><div className="table-name"><span className="table-icon"><Receipt size={16}/></span><span><strong>{e.title}</strong><small>{displayRef('EXP',e.displayNumber)}</small><small>{e.documentCount??0}/3 audit documents</small></span></div></td>
   {isAdmin&&<td><div className="mea-owner"><strong>{e.owner||'Unknown user'}</strong><small title={e.ownerId||'Not recorded'}>ID: {displayRef('EMP',e.ownerDisplayNumber)}</small></div></td>}
   <td>{e.category}<small style={{display:'block',color:'#708ba4'}}>{e.subcategory||''}</small></td><td className="strong">{money(e.amount)}</td><td>{e.date}</td>
   <td><Pill tone={e.status==='Approved'?'green':e.status==='Pending'?'amber':'blue'} dot>{e.status}</Pill></td>
   <td><div style={{display:'flex',alignItems:'center',gap:8}}><button className="tiny-icon" title="View expense" onClick={()=>viewExpense(e)}><Eye size={17}/></button>{canEdit&&e.status==='Pending'&&<button className="tiny-icon" title="Edit expense" onClick={()=>openEditExpense(e)}><Pencil size={16}/></button>}</div></td>
 </tr>):<tr><td colSpan={isAdmin?7:6}><Empty/></td></tr>}</DataTable>;
 const adChartRows=accounts.filter(a=>a.coverage?.complete && a.metrics?.spendPKR!=null).map(a=>({ ...a, label:`${a.platform} (${a.name})`, spend:Number(a.metrics.spendPKR) }));
 const hasManualTrend=chartData.some(point=>Number(point.spend)>0 || (point.adSpend!=null&&Number(point.adSpend)>0));
 const mainDashboard=()=> !isAdmin ? <><Heading title={`Welcome, ${currentUser.name.split(' ')[0]}`} subtitle="Track your expense entries and approval status." action={topAction}/><div className="kpi-grid">{[{label:'My Monthly Allocation',value:money(dashboard?.myBudget?.limit??0),icon:Wallet},{label:'Available for New Expenses',value:money(dashboard?.myBudget?.availableToCreate??0),icon:Target},{label:'Reserved / Pending',value:money(dashboard?.myBudget?.pending??0),icon:Clock3},{label:'Approved Spend',value:money(dashboard?.mySpend??0),icon:CheckCircle2}].map(k=><Card className="kpi-card" key={k.label}><div className="kpi-top"><span>{k.label}</span><div className="kpi-icon blue"><k.icon size={20}/></div></div><div className="kpi-value">{k.value}</div></Card>)}</div><Panel title="My Category Budgets" sub={`Assigned amounts for ${budgetMonth}. Pending requests reserve money.`} right={<Btn variant="subtle" onClick={()=>navigate('Budgets')}>View details <ArrowRight size={15}/></Btn>}>{!myBudgets.items.length?<Empty title="No budget assigned" desc="Ask Admin to allocate a monthly category budget before creating expenses."/>:<DataTable head={['CATEGORY','ALLOTTED','APPROVED','RESERVED','CAN CREATE']}>{myBudgets.items.map(a=><tr key={a.id}><td className="strong">{a.category} / {a.subcategory}</td><td>{money(a.limit)}</td><td>{money(a.used)}</td><td>{money(a.pending)}</td><td className="strong">{money(a.availableToCreate)}</td></tr>)}</DataTable>}</Panel><Panel title="My Assigned Ad Accounts" sub="Read-only spend and performance; assigned by Admin" right={<Btn variant="subtle" onClick={()=>navigate('Ad Accounts')}>View accounts <ArrowRight size={15}/></Btn>}>{accounts.length?<DataTable head={['PLATFORM','ACCOUNT','PERIOD SPEND (PKR)','LEADS (IF AVAILABLE)']}>{accounts.map(a=><tr key={a.id}><td className="strong">{a.platform}</td><td>{a.name}</td><td>{displaySpendPKR(a.metrics,a.currency)}{sourceCurrencyNote(a.spend,a.currency||a.metrics?.currency)&&<div style={{fontSize:11,color:'#7891a5'}}>{sourceCurrencyNote(a.spend,a.currency||a.metrics?.currency)}</div>}</td><td>{a.leads}</td></tr>)}</DataTable>:<Empty title="No ad accounts assigned" desc="Ask Admin to give you view-only access to a company ad account."/>}</Panel><Panel title="My Recent Expenses" sub="Only your records, returned by Express">{expenseTable(expenses.slice(0,6))}</Panel></> : <><Heading title="Marketing Overview" subtitle="A smarter way to monitor every marketing rupee, campaign and result." action={topAction}/><div className="hero"><div><span className="hero-chip"><Activity size={14}/> Marketing intelligence</span><h2>Every campaign. One clear picture.</h2><p>Keep your advertising, expenses, budgets and audit records beautifully organized in one workspace.</p><Btn variant="white" icon={ArrowRight} onClick={()=>navigate('Reports')}>Explore insights</Btn></div><div className="hero-visual"><div className="hero-orbit orbit-one"/><div className="hero-orbit orbit-two"/><div className="hero-floating"><TrendingUp size={29}/><strong>MEA</strong><small>{dashboard?.syncedAccountCount??0} verified ad accounts</small></div></div></div>
 <div className="kpi-grid">{[{label:'Approved Manual Spend',value:money(dashboard?.totalMarketingSpend??0),icon:Wallet,trend:'Recorded expenses',desc:'Approved manual expenses · selected reporting period',tone:'blue'},{label:'Remaining Budget',value:money(dashboard?.remainingBudget??0),icon:Target,trend:'Budget assigned by Admin',desc:`Of ${money(dashboard?.monthlyBudget??0)} allocated`,tone:'aqua'},{label:'Synced Ad Accounts',value:String(dashboard?.syncedAccountCount??0).padStart(2,'0'),icon:Link2,trend:'Meta · Google · TikTok',desc:`${dashboard?.adAccountCount??0} account(s) registered`,tone:'violet'},{label:'Total Leads',value:dashboard?.liveLeads==null?'—':String(dashboard.liveLeads),icon:Users,trend:'API-reported, selected period',desc:dashboard?.leadCoverage||'Awaiting verified API sync',tone:'green'}].map(k=><Card key={k.label} className="kpi-card"><div className="kpi-top"><span>{k.label}</span><div className={'kpi-icon '+k.tone}><k.icon size={20}/></div></div><div className="kpi-value">{k.value}</div><div className="kpi-foot"><span className="kpi-trend"><TrendingUp size={13}/>{k.trend}</span><small>{k.desc}</small></div></Card>)}</div>
 <div className="analytics-grid"><Panel title="Marketing Spend Overview" sub="Approved manual expense vs verified ad spend (PKR) · selected dates · not added together" right={<Pill>PostgreSQL records</Pill>}>{!hasManualTrend?<Empty title="No spending data in this period" desc="The trend will appear when approved manual expenses or actual synced ads have daily data for these dates."/>:<div className="chart-area"><ResponsiveContainer width="100%" height="100%"><AreaChart data={chartData} margin={{top:14,right:10,bottom:0,left:-20}}><defs><linearGradient id="chartFill" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stopColor="#4cb2e8" stopOpacity=".35"/><stop offset="98%" stopColor="#4cb2e8" stopOpacity=".01"/></linearGradient></defs><CartesianGrid vertical={false} stroke="#edf2f7" strokeDasharray="4 5"/><XAxis dataKey="month" axisLine={false} tickLine={false} tick={{fill:'#8494a9',fontSize:12}}/><YAxis tickFormatter={v=>(v/1000)+'k'} axisLine={false} tickLine={false} tick={{fill:'#8494a9',fontSize:12}}/><Tooltip formatter={v=>money(v)} contentStyle={{borderRadius:14,border:'1px solid #e5edf5',boxShadow:'0 12px 32px #143d6018'}}/><Area type="monotone" name="Manual expenses (PKR)" dataKey="spend" stroke="#1172b5" strokeWidth={3} fill="url(#chartFill)" activeDot={{r:6,stroke:'#fff',strokeWidth:3}}/><Area type="monotone" name="Advertising spend (PKR)" dataKey="adSpend" stroke="#35a5bf" strokeWidth={2} fillOpacity={0} fill="none" connectNulls={false} dot={false}/></AreaChart></ResponsiveContainer></div>}</Panel>
 <Panel title="Advertising Channels" sub={`Advertising spend in PKR · ${periodLabel(reportingPeriod)} · foreign currencies require approved FX`} right={<button className="tiny-icon" title="Open ad accounts" onClick={()=>navigate('Ad Accounts')}><ArrowUpRight size={18}/></button>}>{adChartRows.length===0?<Empty title="No synced ad spending for this period" desc="Verify accounts and fetch the selected dates. Incomplete/foreign-currency reports are not added to PKR totals."/>:<><div className="bar-area" style={{height:Math.max(230,adChartRows.length*58)}}><ResponsiveContainer width="100%" height="100%"><BarChart layout="vertical" data={adChartRows} margin={{top:10,right:20,bottom:0,left:0}}><CartesianGrid horizontal={false} stroke="#edf2f7" strokeDasharray="3 4"/><XAxis type="number" axisLine={false} tickLine={false} tickFormatter={v=>(v/1000)+'k'} tick={{fill:'#8494a9',fontSize:11}}/><YAxis type="category" dataKey="label" width={196} axisLine={false} tickLine={false} tick={{fill:'#425771',fontSize:11}}/><Tooltip formatter={v=>money(v)} labelFormatter={label=>label} contentStyle={{borderRadius:12,border:'1px solid #e5edf5'}}/><Bar dataKey="spend" name="Ad spend (PKR)" radius={[0,9,9,0]} barSize={24}>{adChartRows.map((a,i)=><Cell key={a.id} fill={chartPalette[i%chartPalette.length]}/>)}</Bar></BarChart></ResponsiveContainer></div><div className="legend">{adChartRows.map((a,i)=><span key={a.id}><i style={{background:chartPalette[i%chartPalette.length]}}/>{a.platform} ({a.name})</span>)}</div></>}</Panel></div>
 <div className="bottom-grid"><Panel title="Recent Expenses" sub="Recorded expenses from the backend" right={<Btn variant="subtle" onClick={()=>navigate('Expenses')}>View all <ArrowRight size={15}/></Btn>}>{expenseTable(expenses.slice(0,4))}</Panel><Panel title="Budget Health" sub={`Budget context · ${budgetMonth} (monthly, not custom range)`}><div className="budget-ring-wrap"><div className="budget-ring" style={{background:`conic-gradient(#1774bd 0% ${Math.min(100,Math.round(100*(dashboard?.monthlyBudget?dashboard?.totalMarketingSpend||0:0)/Math.max(1,(dashboard?.monthlyBudget??0))))}%,#e5f2fa 0% 100%)`}}><div><b>{Math.round(100*(dashboard?.monthlyBudget?dashboard?.totalMarketingSpend||0:0)/Math.max(1,(dashboard?.monthlyBudget??0)))}%</b><small>Used</small></div></div><div className="budget-numbers"><span>Allocated <b>{money(dashboard?.monthlyBudget??0)}</b></span><span>Spent <b>{money(dashboard?.totalMarketingSpend??0)}</b></span><span>Remaining <b className="green-text">{money(dashboard?.remainingBudget??0)}</b></span></div></div><div className="budget-note"><CheckCircle2 size={17}/> Company monthly budget allocations</div></Panel></div></>;
 const accountsPage=()=> <AdAccountsPage accounts={accounts} isAdmin={isAdmin} team={team} onRefresh={loadData} notify={notify} reportingPeriod={reportQuery}/>;
 const attributionPage=()=> <CounsellorAttributionPage accounts={accounts} isAdmin={isAdmin} notify={notify} reportingPeriod={reportQuery}/>;
 const expensesPage=()=> <><Heading title="Expense Management" subtitle="Manage marketing spending and maintain reliable records." action={<>{isAdmin&&<Btn variant="outline" icon={Download} onClick={()=>window.print()}>Print / Save PDF</Btn>}{topAction}</>}/><div className="mini-stats">{[{n:'Total entries',v:expenses.length,ic:Receipt},{n:'Pending review',v:expenses.filter(e=>e.status==='Pending').length,ic:Clock3},{n:'Approved',v:expenses.filter(e=>e.status==='Approved').length,ic:CheckCircle2}].map(s=><Card className="mini-stat" key={s.n}><s.ic size={20}/><div><small>{s.n}</small><strong>{s.v}</strong></div></Card>)}</div><Panel title="All Expenses" sub="Search and filter your spending records" right={<div className="table-controls"><div className="input-search"><Search size={16}/><input placeholder="Search expenses..." value={search} onChange={e=>setSearch(e.target.value)}/></div><select value={filter} onChange={e=>setFilter(e.target.value)}><option>All</option><option>Pending</option><option>In Review</option><option>Approved</option><option>Rejected</option></select></div>}>{expenseTable(filtered)}</Panel></>;
 const budgetsPage=()=>!isAdmin?<><Heading title="My Allocated Budget" subtitle="Your allowed expense amounts for each marketing category and selected month."/><div className="budget-month-filter"><label htmlFor="my-budget-month">Select month</label><input id="my-budget-month" type="month" value={budgetMonth} onChange={e=>setBudgetMonth(e.target.value||monthNow())}/><span>Pending / In Review amounts are reserved; rejected requests release funds.</span></div><div className="kpi-grid">{[{label:'Allotted',value:myBudgets.overall.limit},{label:'Approved Spend',value:myBudgets.overall.used},{label:'Reserved Requests',value:myBudgets.overall.pending},{label:'Available to Create',value:myBudgets.overall.availableToCreate}].map(x=><Card className="kpi-card" key={x.label}><div className="kpi-top"><span>{x.label}</span><Wallet size={20}/></div><div className="kpi-value">{money(x.value)}</div></Card>)}</div>{myBudgets.items.length===0?<div className="info-strip"><Info size={19}/><div><strong>No budget assigned for {budgetMonth}</strong><small>Admin needs to assign a category/subcategory company budget, then your employee allocation. You cannot create expenses until then.</small></div></div>:<div className="budget-grid">{myBudgets.items.map(a=><Card className="budget-card" key={a.id}><div className="budget-card-top"><span className="budget-badge"><Wallet size={19}/></span><Pill tone={a.availableToCreate===0?'amber':'green'}>{a.utilizationPercent}% committed</Pill></div><h3>{a.category}</h3><p>{a.subcategory}</p><p>Allocated for {budgetMonth}</p><div className="budget-amount">{money(a.availableToCreate)} <span>available / {money(a.limit)} assigned</span></div><Progress value={a.utilizationPercent}/><div className="budget-card-foot"><span>Approved</span><strong>{money(a.used)}</strong></div><div className="budget-card-foot"><span>Pending reserved</span><strong>{money(a.pending)}</strong></div><div className="budget-card-foot"><span>New expense maximum</span><strong>{money(a.availableToCreate)}</strong></div></Card>)}</div>}</> : <><Heading title="Budget Management" subtitle="Monthly category/subcategory budgets, approved spend and reserved exposure." action={<><Btn variant="outline" icon={Info} onClick={()=>setModal('budgetInfo')}>Budget policy</Btn><Btn variant="outline" disabled={isPastBudgetMonth} icon={Plus} onClick={()=>{setNewBudget({month:budgetMonth,category:'',subcategory:'',limit:''});setModal('budgetCreate')}}>New allocation</Btn><Btn icon={Wallet} disabled={isPastBudgetMonth||budgets.length===0} onClick={()=>{if(!apiOnline)return notify('Start backend first');setBudgetForm({id:'',limit:''});setModal('budgetEdit')}}>Edit budgets</Btn></>}/><div className="info-strip"><ShieldCheck size={19}/><div><strong>Approval-based budget controls · PostgreSQL-backed</strong><small>New expenses reserve assigned employee category budgets immediately. Admin must create category/subcategory budgets first, then employee allocations. Rejections release reservations. Actual ad platform spend is shown only after a connected account has been verified and synchronized.</small></div></div><div className="budget-month-filter"><label htmlFor="budget-month">Budget month</label><input id="budget-month" type="month" value={budgetMonth} onChange={e=>setBudgetMonth(e.target.value||monthNow())}/><span>{isPastBudgetMonth?'Read-only past month — budget actions are disabled':`Shown for ${budgetMonth} · budget records are persisted in the shared PostgreSQL database`}</span></div>{budgets.length===0&&<div className="info-strip"><Info size={18}/><div><strong>No allocations defined for {budgetMonth}</strong><small>{isPastBudgetMonth?'This month has no recorded allocations. Past months cannot be edited.':'Start by creating your own monthly allocations. No preset budgets are preloaded.'}</small></div></div>}<div className="budget-grid">{budgets.map((b,i)=><Card className="budget-card" key={b.id||'overall'}><div className="budget-card-top"><span className="budget-badge"><Wallet size={18}/></span><Pill tone={(b.limit&&b.used/b.limit>=.85)?'amber':'green'}>{b.limit?Math.round(b.used/b.limit*100):0}% used</Pill></div><h3>{b.name}</h3><p>{b.caption}</p><div className="budget-amount">{money(b.used)} <span>/ {money(b.limit)}</span></div><Progress value={b.limit?100*b.used/b.limit:0}/><div className="budget-card-foot"><span>Remaining to approve</span><strong>{money(b.remaining??Math.max(0,b.limit-b.used))}</strong></div><div className="budget-card-foot"><span>Pending / in-review exposure</span><strong>{money(b.pending||0)}</strong></div>{b.id&&<div className="budget-card-foot"><span>Not assigned to users</span><strong>{money(b.unassignedToUsers||0)}</strong></div>}{(b.pending||0)>0&&<div className="budget-subnote">Projected if every pending request is approved: {money(b.projected||0)}</div>}</Card>)}</div><Panel title="Employee Category Allocations" sub="Assign each user a category-wise limit under the monthly company category budget." right={<Btn disabled={isPastBudgetMonth||budgets.length===0} icon={Plus} onClick={()=>{setAssignForm({month:budgetMonth,userId:team.find(u=>u.status==='Active'&&u.role==='Employee')?.id||team[0]?.id||'',category:'',subcategory:'',limit:''});setModal('employeeAllocation')}}>Assign to Employee</Btn>}>{employeeBudgets.length===0?<Empty title="No user allocations" desc="First create company category budgets, then assign category limits to employees."/>:<DataTable head={['EMPLOYEE / USER ID','CATEGORY','ALLOTTED','APPROVED','RESERVED','AVAILABLE','ACTION']}>{employeeBudgets.map(a=><tr key={a.id}><td><strong>{a.userName}</strong><small style={{display:'block',fontSize:10}}>ID: {displayRef('EMP',team.find(u=>u.id===a.userId)?.displayNumber)}</small></td><td>{a.category} / {a.subcategory}</td><td>{money(a.limit)}</td><td>{money(a.used)}</td><td>{money(a.pending)}</td><td className="strong">{money(a.availableToCreate)}</td><td><Btn variant="subtle" disabled={isPastBudgetMonth} onClick={()=>{setEditAssignForm({id:a.id,limit:String(a.limit)});setModal('employeeAllocationEdit')}}>Edit</Btn></td></tr>)}</DataTable>}</Panel></>;
 const auditPage=()=> <><Heading title="Audit & Approvals" subtitle="Maintain expense traceability and support CA verification." action={<Btn variant="outline" icon={FileText} onClick={()=>setModal('auditInfo')}>Audit guidelines</Btn>}/><div className="mini-stats">{[{n:'Pending reviews',v:expenses.filter(e=>e.status==='Pending').length,ic:Clock3},{n:'In review',v:expenses.filter(e=>e.status==='In Review').length,ic:Eye},{n:'Approved',v:expenses.filter(e=>e.status==='Approved').length,ic:CheckCheck}].map(s=><Card className="mini-stat" key={s.n}><s.ic size={20}/><div><small>{s.n}</small><strong>{s.v}</strong></div></Card>)}</div><Panel title="Verification Queue" sub="3 supporting documents required before Admin can approve">{expenseTable(expenses.filter(e=>['Pending','In Review'].includes(e.status)).sort((a,b)=>(a.status==='In Review'?0:1)-(b.status==='In Review'?0:1)))}</Panel></>;
 const reportsPage=()=> <><Heading title="Reports & Insights" subtitle="Create a clear picture of channel efficiency and marketing spending." action={<Btn icon={Download} onClick={()=>window.print()}>Print / Save PDF</Btn>}/><div className="info-strip"><FileText size={18}/><div><strong>Recorded data and verified API snapshots only</strong><small>Print / Save PDF uses the browser. Automated and verified PDF exports will be added in Express.</small></div></div><div className="mini-stats">{[{n:'Advertising Spend (PKR)',v:dashboard?.adSpendPKR!=null&&dashboard?.syncedAccountCount?money(dashboard.adSpendPKR):dashboard?.fxPendingAccountCount?'FX rate pending':'—',ic:Wallet},{n:'Ads Tracked',v:accounts.some(a=>a.lastSyncedAt)?accounts.reduce((s,a)=>s+(Number(a.ads)||0),0):'—',ic:Target},{n:'Leads Recorded',v:accounts.some(a=>a.lastSyncedAt && a.leads!=null)?accounts.reduce((s,a)=>s+(Number(a.leads)||0),0):'—',ic:Users}].map(s=><Card className="mini-stat" key={s.n}><s.ic size={20}/><div><small>{s.n}</small><strong>{s.v}</strong></div></Card>)}</div><Panel title="Channel Breakdown" sub={`Native PKR spend needs no conversion · ${periodLabel(reportingPeriod)} · foreign currencies require approved FX`}><DataTable head={['AD PLATFORM','PERIOD SPEND','ALL ADS','LEADS','COST / LEAD']}>{accounts.filter(a=>a.lastSyncedAt).length===0?<tr><td colSpan={5}>No verified ad reporting yet. Register an authorized account, verify connection, then sync.</td></tr>:accounts.filter(a=>a.lastSyncedAt).map(a=><tr key={a.id}><td className="strong">{a.platform}</td><td>{displaySpendPKR(a.metrics,a.currency)}{sourceCurrencyNote(a.spend,a.currency||a.metrics?.currency)&&<div style={{fontSize:11,color:'#7891a5'}}>{sourceCurrencyNote(a.spend,a.currency||a.metrics?.currency)}</div>}</td><td>{a.lastSyncedAt?(a.ads??'—'):'—'}</td><td>{a.lastSyncedAt?(a.leads??'—'):'—'}</td><td>{a.lastSyncedAt&&a.leads>0&&a.metrics?.spendPKR!=null?money(a.metrics.spendPKR/a.leads):'—'}</td></tr>)}</DataTable></Panel></>;
 const categoriesPage=()=> <><Heading title="Marketing Categories" subtitle="One consistent category/subcategory structure for budgets and expenses." action={isAdmin&&<Btn icon={Plus} onClick={()=>setModal('category')}>Add Main Category</Btn>}/><div className="category-grid">{categoryTree.map((c,i)=>{const Icon=icons[i%icons.length];return <Card className="category-card" key={c.id}><div className="category-symbol"><Icon size={23}/></div><strong>{c.name}</strong><p>{c.subcategories.length} subcategories</p><div className="mea-subtags">{c.subcategories.map(x=><span key={x.id}>{x.name}</span>)}{!c.subcategories.length&&<span>No subcategories yet</span>}</div>{isAdmin&&<button type="button" className="btn btn-outline" style={{marginTop:14}} onClick={()=>{setSubcategoryForm({categoryId:c.id,name:''});setModal('subcategory')}}><Plus size={14}/> Add Subcategory</button>}</Card>})}</div></>;

 
 const views={'Dashboard':mainDashboard,'Ad Accounts':accountsPage,'Counsellor Attribution':attributionPage,'Expenses':expensesPage,'Budgets':budgetsPage,'Audit & Approvals':auditPage,'Reports':reportsPage,'Categories':categoriesPage};
 return <div className={'app-shell '+(dark?'dark-theme':'')}><style>{styles + uiPolishStyles + budgetFinalStyles + '.mea-subtags{display:flex;flex-wrap:wrap;gap:7px;margin-top:13px}.mea-subtags span{background:#edf7ff;border:1px solid #d1e7f7;color:#27668a;border-radius:999px;padding:5px 9px;font-size:11px;font-weight:700}'}</style><div className={'mobile-overlay '+(mobileMenu?'visible':'')} onClick={()=>setMobileMenu(false)}/><aside className={'sidebar '+(compact?'is-compact':'')+' '+(mobileMenu?'is-open':'')}><button type="button" className="brand brand-action" onClick={()=>navigate('Dashboard')} title="Go to Dashboard" aria-label="Scholarshiphive - Go to Dashboard"><div className="brand-logo"><img src="/marketing-assets/company-icon.jpg" alt="Scholarshiphive logo"/></div>{!compact&&<div className="brand-name"><b>Scholarshiphive</b><span>MARKETING EXPENSES</span></div>}</button><div className="nav-section-label">{compact?'•••':'WORKSPACE'}</div><nav>{NAV.filter(([name])=>isAdmin||['Dashboard','Ad Accounts','Counsellor Attribution','Expenses','Budgets','Categories'].includes(name)).map(([name,Icon])=><button title={name} key={name} onClick={()=>navigate(name)} className={'nav-link '+(page===name?'selected':'')}><Icon size={19}/>{!compact&&<span>{name}</span>}{page===name&&<i className="nav-selected-dot"/>}</button>)}</nav><div className="sidebar-bottom">{!compact&&<div className="sidebar-promo"><div className="promo-icon"><Activity size={19}/></div><strong>Stay in control</strong><p>Every marketing expense, organized in one place.</p><button onClick={()=>navigate('Reports')}>View reports <ArrowRight size={14}/></button></div>}<button className="sidebar-collapse" onClick={()=>setCompact(v=>!v)}>{compact?<PanelLeftOpen size={18}/>:<PanelLeftClose size={18}/>} {!compact&&'Collapse sidebar'}</button></div></aside>
 <div className={'app-main '+(compact?'is-compact':'')}><header className="topbar"><div className="top-left"><button className="mobile-trigger icon-btn" onClick={()=>setMobileMenu(true)} aria-label="Open navigation"><Menu size={22}/></button><div className="breadcrumb">Workspace <ChevronRight size={15}/><b>{page}</b></div></div><div className="top-actions"><span className="demo-tag"><span/>{apiOnline?'API CONNECTED':'API OFFLINE'}</span><button className="icon-btn head-icon" title="Refresh from Express API" disabled={loading} onClick={refresh}><RefreshCw size={18}/></button><div className="notification-anchor"><button className="icon-btn head-icon" title="Notifications" onClick={()=>setNotice(v=>!v)}><Bell size={19}/><i className="notification-dot"/></button>{notice&&<div className="notification-pop"><b>Notifications</b><p>Live notifications require a production worker; account sync runs on verified backend accounts.</p><Btn variant="subtle" onClick={()=>setNotice(false)}>Got it</Btn></div>}</div><div className="top-divider"/><button className="profile" onClick={()=>setModal('profile')} title="Account details"><div className="avatar">{currentUser.initials}</div><div className="profile-label"><strong>{currentUser.name}</strong><small>{currentUser.role} · {displayRef(currentUser.role==='Admin'?'ADM':'EMP',currentUser.displayNumber)}</small></div><ChevronDown size={15}/></button></div></header>
 <div className="content"><div className="demo-banner"><Info size={16}/><span><b>{apiOnline?'Backend connected:':'API offline:'}</b> {apiOnline?'Financial records load from the backend database. Ad data is shown only after verified platform sync.':'The Marketing Analyzer API (/api/v1) could not be reached. Please refresh or try again shortly. '+(loadError||'No records loaded.')}</span><button title="View integration status" onClick={()=>navigate('Dashboard')}><ArrowRight size={17}/></button></div>{['Dashboard','Ad Accounts','Reports','Counsellor Attribution','Expenses'].includes(page)&&<ReportingPeriodPicker value={reportingPeriod} onChange={setReportingPeriod}/>} {views[page]()}<footer className="footer"><span>© 2026 Scholarshiphive · Market Expenses Analyzer</span><span>React Web · {currentUser.role} session</span></footer></div></div>
 {toast&&<div className="toast"><CheckCircle2 size={19}/>{toast}<button onClick={()=>setToast('')}><X size={15}/></button></div>}
 {modal==='expense'&&<Modal title="Add Marketing Expense" sub="Record an expense against an approved allocation." onClose={()=>setModal(null)}><form onSubmit={addExpense} className="dialog-form"><label>Expense title<input required placeholder="e.g. October podcast sponsorship" value={form.title} onChange={e=>setForm({...form,title:e.target.value})}/></label><div className="form-grid"><label>Category / Subcategory (assigned only)<select required value={selectedAllowance?selectedAllowance.id:''} onChange={e=>{const a=expenseAllowance?.items?.find(x=>x.id===e.target.value);setForm({...form,category:a?.category||'',subcategory:a?.subcategory||''})}}><option value="">Choose allocated category</option>{(expenseAllowance?.items||[]).map(x=><option key={x.id} value={x.id} disabled={x.availableToCreate<=0}>{x.category} / {x.subcategory} — {money(x.availableToCreate)} available</option>)}</select></label><label>Amount (PKR)<input required type="number" min="1" placeholder="50000" value={form.amount} onChange={e=>setForm({...form,amount:e.target.value})}/></label></div><div className="form-grid"><label>Expense date<input required type="date" value={form.date} onChange={e=>setForm({...form,date:e.target.value})}/></label><label>Vendor / payee<input placeholder="Optional" maxLength={200} value={form.vendor} onChange={e=>setForm({...form,vendor:e.target.value})}/></label></div><div className="expense-allowance"><strong>{selectedAllowance?`Budget for ${form.category}: ${money(selectedAllowance.limit)}`:'No assigned category budget for this month'}</strong><span>{selectedAllowance?`Approved ${money(selectedAllowance.used)} · Reserved ${money(selectedAllowance.pending)} · You can create up to ${money(selectedAllowance.availableToCreate)}`:'Ask Admin to allocate this category/month first. Expense creation is blocked.'}</span>{selectedAllowance&&Number(form.amount)>selectedAllowance.availableToCreate&&<em>Amount exceeds available budget.</em>}</div><label>Invoice / reference (optional)<input maxLength={80} placeholder="Invoice or reference number" value={form.reference} onChange={e=>setForm({...form,reference:e.target.value})}/></label><label>Description (optional)<textarea rows={3} maxLength={1000} placeholder="Business purpose or expense notes" value={form.description} onChange={e=>setForm({...form,description:e.target.value})}/></label><div className="modal-foot"><Btn variant="outline" onClick={()=>setModal(null)}>Cancel</Btn><Btn icon={Plus} type="submit" disabled={!canCreateExpense}>Add Expense</Btn></div></form></Modal>}
 {modal==='expenseEdit'&&<Modal title="Edit Marketing Expense" sub="Only pending expenses can be modified before submission." onClose={()=>setModal(null)}><form onSubmit={saveEditedExpense} className="dialog-form"><label>Expense title<input required minLength={2} maxLength={200} value={editForm.title||''} onChange={e=>setEditForm({...editForm,title:e.target.value})}/></label><div className="form-grid"><label>Category / Subcategory (assigned only)<select value={editSelectedAllowance?.id||''} required onChange={e=>{const a=editAllowance?.items?.find(x=>x.id===e.target.value);setEditForm({...editForm,category:a?.category||'',subcategory:a?.subcategory||''})}}><option value="">Choose allocated category</option>{(editAllowance?.items||[]).map(a=><option key={a.id} value={a.id}>{a.category} / {a.subcategory}</option>)}</select></label><label>Amount (PKR)<input required type="number" step="0.01" min="0.01" value={editForm.amount||''} onChange={e=>setEditForm({...editForm,amount:e.target.value})}/></label></div><div className="form-grid"><label>Expense date<input required type="date" value={editForm.date||''} onChange={e=>setEditForm({...editForm,date:e.target.value})}/></label><label>Vendor / payee<input maxLength={200} value={editForm.vendor||''} onChange={e=>setEditForm({...editForm,vendor:e.target.value})}/></label></div><div className="expense-allowance"><strong>{editSelectedAllowance?`Assigned: ${money(editSelectedAllowance.limit)} · ${editForm.category}`:'No budget allocated for this category/month'}</strong><span>{editSelectedAllowance?`Available for new expenses: ${money(editSelectedAllowance.availableToCreate)}. Your existing pending amount remains reserved while editing.`:'Changing to an unallocated category is not allowed.'}</span></div><label>Invoice / reference<input maxLength={80} value={editForm.reference||''} onChange={e=>setEditForm({...editForm,reference:e.target.value})}/></label><label>Description<textarea rows={3} maxLength={1000} value={editForm.description||''} onChange={e=>setEditForm({...editForm,description:e.target.value})}/></label><div className="modal-foot"><Btn variant="outline" onClick={()=>setModal(null)}>Cancel</Btn><Btn type="submit" icon={Pencil} disabled={!canEditExpense}>Save Changes</Btn></div></form></Modal>}
 {modal==='expenseDelete'&&canEdit&&pendingDelete&&<Modal title="Delete Pending Expense?" sub="This deletion cannot be undone." onClose={()=>setModal(null)}><div className="modal-copy">Remove <b>{pendingDelete.title}</b> ({money(pendingDelete.amount)})? Only Pending expenses can be deleted.</div><div className="modal-foot"><Btn variant="outline" onClick={()=>setModal(null)}>Cancel</Btn><Btn icon={Trash2} onClick={deleteExpense}>Delete Expense</Btn></div></Modal>}
 {modal==='budgetCreate'&&isAdmin&&<Modal title="Create Monthly Allocation" sub="Create a company monthly allocation." onClose={()=>setModal(null)}><form className="dialog-form" onSubmit={createBudget}><label>Month<input required type="month" min={monthNow()} value={newBudget.month} onChange={e=>setNewBudget({...newBudget,month:e.target.value})}/></label><label>Category<select required value={newBudget.category} onChange={e=>setNewBudget({...newBudget,category:e.target.value,subcategory:''})}><option value="">Choose category</option>{categoryTree.map(c=><option value={c.name} key={c.id}>{c.name}</option>)}</select></label><label>Subcategory<select required value={newBudget.subcategory} onChange={e=>setNewBudget({...newBudget,subcategory:e.target.value})}><option value="">Choose subcategory</option>{subcategoriesFor(newBudget.category).map(sub=><option value={sub.name} key={sub.id}>{sub.name}</option>)}</select></label><label>Monthly budget (PKR)<input required type="number" step="0.01" min="0.01" value={newBudget.limit} onChange={e=>setNewBudget({...newBudget,limit:e.target.value})}/></label><div className="modal-foot"><Btn variant="outline" onClick={()=>setModal(null)}>Cancel</Btn><Btn icon={Plus} type="submit">Create Allocation</Btn></div></form></Modal>}
 {modal==='category'&&<Modal title="Add Marketing Category" sub="Stored in the shared ScholarshipHive PostgreSQL database." onClose={()=>setModal(null)}><form className="dialog-form" onSubmit={addCategory}><label>Category name<input required minLength={2} maxLength={120} placeholder="e.g. Outdoor Advertising" value={categoryForm} onChange={e=>setCategoryForm(e.target.value)}/></label><div className="modal-foot"><Btn variant="outline" onClick={()=>setModal(null)}>Cancel</Btn><Btn type="submit" icon={Plus}>Add Category</Btn></div></form></Modal>}
 {modal==='subcategory'&&isAdmin&&<Modal title="Add Marketing Subcategory" sub="New subcategories appear in Budgets and Expense allocations." onClose={()=>setModal(null)}><form className="dialog-form" onSubmit={addSubcategory}><label>Subcategory name<input required minLength={2} maxLength={120} value={subcategoryForm.name} onChange={e=>setSubcategoryForm({...subcategoryForm,name:e.target.value})} placeholder="e.g. Local Radio Advertising"/></label><div className="modal-foot"><Btn variant="outline" onClick={()=>setModal(null)}>Cancel</Btn><Btn type="submit" icon={Plus}>Add Subcategory</Btn></div></form></Modal>}
 {modal==='budgetEdit'&&<Modal title="Edit Monthly Budget" sub="Update the current monthly allocation." onClose={()=>setModal(null)}><form className="dialog-form" onSubmit={updateBudget}><label>Budget allocation<select required value={budgetForm.id} onChange={e=>{const b=budgets.find(x=>x.id===e.target.value);setBudgetForm({id:e.target.value,limit:b?String(b.limit):''})}}><option value="">Select allocation</option>{budgets.filter(x=>x.id).map(b=><option value={b.id} key={b.id}>{b.name}</option>)}</select></label><label>Monthly limit (PKR)<input required type="number" min="1" step="0.01" value={budgetForm.limit} onChange={e=>setBudgetForm({...budgetForm,limit:e.target.value})}/></label><div className="modal-foot"><Btn variant="outline" onClick={()=>setModal(null)}>Cancel</Btn><Btn type="submit">Save Budget</Btn></div></form></Modal>}
 {modal==='profile'&&<Modal title="My Account" sub="Signed in with your ScholarshipHive ERP account." onClose={()=>setModal(null)}><div className="detail-row"><span>Name</span><strong>{currentUser.name}</strong></div><div className="detail-row"><span>Role</span><Pill>{currentUser.role}</Pill></div><div className="detail-row"><span>Access</span><strong>ScholarshipHive single sign-on</strong></div><div className="modal-foot"><Btn onClick={()=>setModal(null)}>Close</Btn></div></Modal>}
 {modal==='employeeAllocation'&&isAdmin&&<Modal title="Assign Employee Category Budget" sub="Monthly limit under the corresponding company category allocation." onClose={()=>setModal(null)}><form className="dialog-form" onSubmit={createEmployeeBudget}><label>Month<input type="month" min={monthNow()} required value={assignForm.month} onChange={e=>setAssignForm({...assignForm,month:e.target.value})}/></label><label>Employee / user<select required value={assignForm.userId} onChange={e=>setAssignForm({...assignForm,userId:e.target.value})}><option value="">Select user</option>{team.filter(u=>u.status==='Active').map(u=><option key={u.id} value={u.id}>{u.name} ({u.role}) · {u.id.slice(0,8)}</option>)}</select></label><label>Expense category<select value={assignForm.category} required onChange={e=>setAssignForm({...assignForm,category:e.target.value,subcategory:''})}><option value="">Choose category</option>{categoryTree.map(c=><option key={c.id} value={c.name}>{c.name}</option>)}</select></label><label>Expense subcategory<select required value={assignForm.subcategory} onChange={e=>setAssignForm({...assignForm,subcategory:e.target.value})}><option value="">Choose subcategory</option>{subcategoriesFor(assignForm.category).map(sub=><option key={sub.id} value={sub.name}>{sub.name}</option>)}</select></label><label>Assigned amount (PKR)<input required type="number" min="0.01" step="0.01" value={assignForm.limit} onChange={e=>setAssignForm({...assignForm,limit:e.target.value})}/></label><div className="expense-allowance"><strong>Company category allocation required first</strong><span>Employee allocations for each category/subcategory cannot exceed its monthly company budget.</span></div><div className="modal-foot"><Btn variant="outline" onClick={()=>setModal(null)}>Cancel</Btn><Btn type="submit">Assign Budget</Btn></div></form></Modal>}
 {modal==='employeeAllocationEdit'&&isAdmin&&<Modal title="Edit Employee Budget" sub="Cannot reduce below existing approved + reserved expense amounts." onClose={()=>setModal(null)}><form className="dialog-form" onSubmit={editEmployeeBudget}><label>New monthly limit (PKR)<input type="number" min="0.01" step="0.01" required value={editAssignForm.limit} onChange={e=>setEditAssignForm({...editAssignForm,limit:e.target.value})}/></label><div className="modal-foot"><Btn variant="outline" onClick={()=>setModal(null)}>Cancel</Btn><Btn type="submit">Save Allocation</Btn></div></form></Modal>}
 {modal==='budgetInfo'&&<Modal title="Budget Policy" sub="Budget limits are enforced by the database-backed API." onClose={()=>setModal(null)}><div className="modal-copy">Admin first sets company monthly category/subcategory limits, then assigns a category, subcategory and amount to each employee. Pending and In Review expenses reserve budget immediately. Creation, edits, submission and approval verify both user and company capacity. Rejecting a request releases its reservation. Live ad platforms may still overspend between API updates.</div><div className="modal-foot"><Btn onClick={()=>setModal(null)}>Understood</Btn></div></Modal>}
 {modal==='auditInfo'&&<Modal title="CA Audit & Verification" sub="Three documents per expense; Admin approves or rejects." onClose={()=>setModal(null)}><div className="modal-copy">Employee uploads 3 documents (PDF, JPG or PNG), submits for review, then Admin approves or rejects with reason. Production uploads are stored through the configured backend document store; review your retention and audit policy before rollout.</div><div className="modal-foot"><Btn onClick={()=>setModal(null)}>Understood</Btn></div></Modal>}
 {modal&&typeof modal==='object'&&<Modal title={modal.type==='accountDetail'?modal.data.platform:modal.data.title} sub="Record details" onClose={()=>setModal(null)}>{(modal.type==='accountDetail'?[['Account',modal.data.name],['Account reference',displayRef('ACC',modal.data.displayNumber)],['Ad spend',money(modal.data.spend)],['Active ads',modal.data.ads],['Leads',modal.data.leads],['Connection','Not connected']]:[['ID',modal.data.id],...(isAdmin?[['Created by',modal.data.owner||'Unknown'],['User ID',modal.data.ownerId||'Not recorded']]:[]),['Category',`${modal.data.category} / ${modal.data.subcategory||''}`],['Amount',money(modal.data.amount)],['Date',modal.data.date],['Status',modal.data.status],['Reference',modal.data.reference||'—'],['Description',modal.data.description||'—']]).map(([k,v])=><div className="detail-row" key={k}><span>{k}</span><strong>{v}</strong></div>)}{modal.type==='expenseDetail'&&<ExpenseAuditPanel key={modal.data.id} expense={modal.data} currentUser={currentUser} canEdit={canEdit} onChanged={()=>refreshExpenseModal(modal.data.id)}/>}
 {modal.type==='expenseDetail'&&canEdit&&modal.data.status==='Pending'&&<div className="modal-foot"><Btn variant="outline" icon={Pencil} onClick={()=>openEditExpense(modal.data)}>Edit Expense</Btn><Btn variant="outline" icon={Trash2} onClick={()=>{setPendingDelete(modal.data);setModal('expenseDelete')}}>Delete</Btn></div>}
 <div className="modal-foot"><Btn onClick={()=>setModal(null)}>Close</Btn></div></Modal>}
 </div>
}
